// protocol object anymore. This does not affect any other
// objects, wl_subsurface objects included.
func (o WlSubcompositor) Destroy() {
	conn := o.raw.Conn()
	conn.SendRequest(o.raw, 0, func() (args []byte, fds []int) {
		o.raw.Destroy()
		return
	})
	return
}

// Create a sub-surface interface for the given surface, and
// associate it with the given parent surface. This turns a
// plain wl_surface into a sub-surface.
//
// The to-be sub-surface must not already have another role, and it
// must not have an existing wl_subsurface object. Otherwise the
// bad_surface protocol error is raised.
//
// Adding sub-surfaces to a parent is a double-buffered operation on the
// parent (see wl_surface.commit). The effect of adding a sub-surface
// becomes visible on the next time the state of the parent surface is
// applied.
//
// The parent surface must not be one of the child surface's descendants,
// and the parent must be different from the child surface, otherwise the
// bad_parent protocol error is raised.
//
// This request modifies the behaviour of wl_surface.commit request on
// the sub-surface, see the documentation on wl_subsurface interface.
func (o WlSubcompositor) GetSubsurface(surface WlSurface, parent WlSurface) WlSubsurface {
	conn := o.raw.Conn()
	var id *raw.Object
	conn.SendRequest(o.raw, 1, func() (args []byte, fds []int) {
		args = make([]byte, 0, 12)
		id, args = conn.MarshalNewID(args, &interfaceWlSubsurface, o.raw.Version())
		args = conn.MarshalObject(args, surface.raw)
		args = conn.MarshalObject(args, parent.raw)
		return
	})
	return As[WlSubsurface](id)
}

