func (o KdeOutputManagementV2) SetUserData(v KdeOutputManagementV2Data) { o.raw.SetUserData(v) }

// Request an outputconfiguration object through which the client can configure
// output devices.
func (o KdeOutputManagementV2) CreateConfiguration() KdeOutputConfigurationV2 {
	conn := o.raw.Conn()
	var id *raw.Object
	conn.SendRequest(o.raw, 0, func() (args []byte, fds []int) {
		args = make([]byte, 0, 4)
		id, args = conn.MarshalNewID(args, &interfaceKdeOutputConfigurationV2, o.raw.Version())
		return
	})
	return As[KdeOutputConfigurationV2](id)
}

